steps.script:
window.__lmc = {
  page: () => document.querySelector('#LibraryMaintenanceConfigPage:not(.hide)'),
  q: (s) => (__lmc.page() || document).querySelector(s),
  qa: (s) => [...(__lmc.page() || document).querySelectorAll(s)],
  card: () => __lmc.q('#LibraryMaintenanceGroupsList article[data-group-id="' + __vars.server.id + '"]'),
  mark: () => { const c = __lmc.card(); if (c) { c.setAttribute('data-lmc-target', 'true'); } return !!c; },
  api: async (path) => { const r = await fetch(ApiClient.getUrl(path), { headers: { Authorization: 'MediaBrowser Token="' + ApiClient.accessToken() + '"', Accept: 'application/json' } }); return { status: r.status, body: r.status === 204 ? null : await r.json() }; },
  hidden: (e) => !e || !!e.closest('.hide')
};
return true;

window.__lmc = {
  page: () => document.querySelector('#LibraryMaintenanceConfigPage:not(.hide)'),
  q: (s) => (__lmc.page() || document).querySelector(s),
  card: () => __lmc.q('#LibraryMaintenanceGroupsList article[data-group-id="' + __vars.server.id + '"]'),
  where: () => { const a = document.activeElement; const card = a && a.closest ? a.closest('article') : null; return { tag: a ? a.tagName : null, text: a ? (a.textContent || '').trim().slice(0, 40) : null, body: !a || a === document.body, card: card ? card.getAttribute('data-group-id') : null, inCompare: !!(a && a.closest && a.closest('.jflm-page-compare')), toggle: !!(a && a.classList && a.classList.contains('jflm-page-compare-toggle')) }; }
};
return true;
